# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["前三轮（113/114/115）查的都是「闸有没有接线」。这轮换一个问法：","","    六道闸都接上线了，那「闸拦不住、钱却在漏」的情况有没有出口？","","=== 一、止损失效的完整链路 ===","","    价格跌破熔断线 -> _close() 发市价卖出","      -> 交易所 5xx / 网络抖 / 熔断中只放行减仓但余额对不上","      -> FillResult(ok=False) -> 退避 3s/6s/12s... 上限 300s -> 下一轮再来","      -> 仓位仍然在手上，价格继续跌","","=== 二、实测：钱在漏，所有仪表都指着「正常」 ===","","真引擎 + 一个永远返回 500 的执行器替身，连续 10 次：","","    第 1 次 _close -> False，退避 3 秒","    第 2 次 _close -> False，退避 6 秒","    ...","    risk_events 里 10 条 close_failed","","    看板 executor = {name:spot, halted:False, reason:}","    state 里没有任何 close 失败相关字段","    Guard: can_open = (True, '')   halted_hard = False","","    四个监控面是否读 close_failed：","       看板 不读 / 哨兵 不读 / 健康自检 不读 / Guard 不读","","退避逻辑本身是对的（该重试的确实在重试）。问题是「止损打不出去」这个事实","没有任何出口——它不是靠 bug 静默，是靠「没有人订阅这个事件」静默。","","和前几轮的区别：前几轮查的是代码路径（闸没接线），","这轮查的是观察者（接线了但没有人看）。","","=== 三、改法：把失败次数变成一条真闸 ===","","Guard 新增 close_fail_streak_changed(streak)，用常量 CLOSE_FAIL_TAG 做前缀，","连续失败到 close_fail_limit 就停开新仓，计数归零即自动解除。","","阈值 5 不是拍的：退避是 3/6/12/24/48 秒，第 5 次失败时已过去约 93 秒，","价格在下跌里足够走出很远；而偶发失败一般第 2 次就恢复，设成 2 会把抖动升级成停机。","","engine._close() 失败/成功两侧都同步，并把 close_fail_count 放进 executor 字段上大屏。","注意只停开新仓——平仓路径完全不受影响，越失效越要继续试着平。","","=== 四、新增 5 条测试（tests/test_close_failure_is_visible.py） ===","","- test_repeated_close_failures_trip_the_guard        连续失败 8 次 -> 停止开新仓","- test_a_couple_of_close_failures_do_not_trip_the_guard  偶发失败不许停摆（防误停）","- test_a_successful_close_clears_the_streak          成功一次计数归零","- test_a_recovered_close_channel_releases_the_guard  通道恢复后自动解除","- test_the_close_failure_count_is_visible_on_the_board  次数必须出现在 state 里","","=== 五、第 4 条是补上来的——而且是它抓到了真 bug ===","","第一轮变异：7 个里杀了 6 个，「恢复不解除闸」存活（4 passed）。","","追下去发现两件事：","","1. 测试缺口：原来的「成功清零」用例只失败 4 次（没到阈值 5），","   闸根本没触发过，「解除」这条路径一次都没走过。","2. 真 bug：补上测试之后它当场红：","","       tag = 平仓连续失败                     # 清除用","       temp_block = 止损通道失效：平仓已连续失败 ...   # 写入用","","   两个字面量根本不是同一个开头，startswith(tag) 永远为假，","   于是这条闸【只会锁死，不会解除】。","","这和第 114 轮「当日亏损没有清除分支」是同一家族：","写和清用了两个不同的字面量，代码读起来完全对称。","","=== 六、最终验证（9 个变异，8 杀 1 等价） ===","","    失败不同步给 Guard                2 failed","    阈值 5 改成 1                     2 failed","    阈值 5 改成 99                    2 failed","    成功不清零计数                     2 failed","    恢复不解除闸                       1 failed","    失败计数不上大屏                    1 failed","    解除时不重新同步                    1 failed","    清除分支用另一个字面量（复刻真 bug）   1 failed","    常量值整体换成别的字符串              5 passed（等价变异）","","最后一条要判性质：把 CLOSE_FAIL_TAG 整体换成另一个字符串，","写入和清除仍然是同一个常量，行为完全一致——这是无效变异，不是缺口。","真正该被杀的是「写和清用了不同的字面量」，那一条已单独验证过。","","全量 563 全绿（558 -> 563）。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":116,"theme":"止损失效没有任何出口——四个监控面一个都不读","new_question":"前三轮查「闸有没有接线」（代码路径），这轮查「观察者」：闸拦不住、钱却在漏的情况有没有出口","discovery":{"scenario":"价格跌破熔断线 -> _close() 失败 -> 退避重试 -> 仓位仍在手上，价格继续跌","measured":"连续 10 次平仓失败后：看板 executor.halted=False、state 无任何 close 失败字段、Guard can_open=(True,'')","observer_audit":"看板/哨兵/健康自检/Guard 四个监控面一个都不读 close_failed","nature":"不是靠 bug 静默，是靠「没有人订阅这个事件」静默"},"fix":{"guard":"close_fail_streak_changed(streak) + CLOSE_FAIL_TAG 常量；连续失败 >= close_fail_limit 则停开新仓，计数归零自动解除","threshold_rationale":"close_fail_limit=5：退避 3/6/12/24/48 秒，第 5 次已过约 93 秒；偶发失败一般第 2 次恢复，设成 2 会把抖动升级成停机","engine":"_close() 失败/成功两侧都调 _sync_close_fail_streak()","board":"close_fail_count 放进 /api/trade/state 的 executor 字段","scope":"只停开新仓，平仓路径完全不受影响"},"tests_added":5,"test_file":"tests/test_close_failure_is_visible.py","bug_found_by_test":{"when":"变异「恢复不解除闸」存活 → 补第 4 条测试 → 当场红","bug":"tag = 平仓连续失败（清除） vs temp_block = 止损通道失效：…（写入），两个字面量不是同一个开头，startswith 恒假","effect":"这条闸只会锁死，不会解除","family":"与第 114 轮「当日亏损没有清除分支」同族：写和清用了两个不同的字面量，代码读起来完全对称","fix":"引用同一个常量 CLOSE_FAIL_TAG"},"mutations":{"失败不同步给 Guard":"2 failed","阈值 5→1":"2 failed","阈值 5→99":"2 failed","成功不清零计数":"2 failed","恢复不解除闸":"1 failed","失败计数不上大屏":"1 failed","解除时不重新同步":"1 failed","清除分支用另一个字面量":"1 failed","常量值整体换成别的字符串":"5 passed（等价变异，非缺口）"},"tests_total":563,"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'止损失效没有任何出口——四个监控面一个都不读，已落成真闸',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()